{
  "title": "夜幕下的信号",
  "scene": "你站在赛博朋克都市的中心，四周是高耸入云的建筑，霓虹灯闪烁着各种广告和标语。前方是一座巨大的企业大楼，门禁森严，但你听闻这里藏有重要的信息。正门的入口处站着两个穿着黑色制服的保安，他们似乎并不友好。旁边的小巷里，一个戴着旧式耳机的流浪者正盯着大楼的窗户。你注意到大楼侧面有一条几乎看不见的通风管道，似乎可以通到楼内。",
  "goal": "潜入大楼获取信息",
  "clue": "流浪者和通风管道",
  "choices": [
    {
      "id": "A",
      "text": "与流浪者交谈",
      "outcome": "流浪者告诉你，他曾经是这家企业的员工，通风管道可以直接通到大楼的安全系统室。他还给了你一个旧式耳机，可以帮助你规避安全系统。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "B",
      "text": "从正门强行闯入",
      "outcome": "保安立刻发现了你，但你利用义体的力量轻松击败了他们。然而，警报已经被触发，大楼内的安全系统迅速启动，你不得不花费更多的时间和精力应对。",
      "result": "partial",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "尝试爬通风管道",
      "outcome": "通风管道非常狭窄，但你成功进入了大楼内部，避开了大部分的安全系统。你找到了安全系统室，但没有合适的工具来绕过系统。",
      "result": "success",
      "next": "next_level"
    }
  ]
}
